/* Newspaper — newsprint gray, blackletter-ish serif heads, column rules */
.theme-newspaper {
  --bg: oklch(0.94 0.008 95);
  --surface: oklch(0.965 0.006 95);
  --surface-2: oklch(0.9 0.01 95);
  --fg: oklch(0.18 0.005 60);
  --fg-muted: oklch(0.44 0.008 60);
  --accent: oklch(0.18 0.005 60);
  --accent-fg: oklch(0.965 0.006 95);
  --accent-2: oklch(0.45 0.16 25);
  --line: oklch(0.18 0.005 60 / 45%);
  --success: oklch(0.45 0.1 150);
  --warning: oklch(0.62 0.12 80);
  --danger: oklch(0.45 0.16 25);

  --radius: 0rem;
  --radius-sm: 0rem;
  --radius-lg: 0rem;
  --radius-pill: 0rem;

  --shadow-1: 0 1px 0 0 var(--line);
  --shadow-2: 0 0 0 1px var(--line);
  --shadow-3: 0 0 0 3px var(--line);
  --glow: none;

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Old Standard TT", Georgia, serif;
  --font-body: "Libre Baskerville", Georgia, serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.26em;

  background-color: var(--bg);
  background-image: repeating-linear-gradient(
    45deg,
    oklch(0.18 0.005 60 / 3%) 0 1px,
    transparent 1px 3px
  );
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-newspaper h1,
.theme-newspaper h2,
.theme-newspaper h3 {
  font-family: var(--font-display);
  font-weight: 900;
  letter-spacing: var(--tracking-display);
  line-height: 1.02;
}

/* signature */
.theme-newspaper { --font-app: "Inter", sans-serif; }

.theme-newspaper { --font-ui: "Inter", sans-serif; }

.theme-newspaper { background-image: radial-gradient(oklch(0.2 0.01 80 / 4%) 1px, transparent 1px); background-size: 4px 4px; }
.theme-newspaper h1 { font-weight: 700; }
.theme-newspaper h2 { border-block: 3px double var(--fg); padding-block: 0.5rem; }
.theme-newspaper ::selection { background: var(--fg); color: var(--bg); }

/* depth */
.theme-newspaper thead th { font-family: var(--font-display); text-transform: uppercase; letter-spacing: 0.14em; font-size: 0.72em; font-weight: 700; border-bottom: 3px double var(--fg); text-align: left; }
.theme-newspaper td { border-bottom: 1px solid var(--line); }
/* physical: vertical column rules between cells, like a broadsheet page */
.theme-newspaper td + td, .theme-newspaper th + th { border-left: 1px solid var(--line); }
.theme-newspaper tbody tr:hover { background: oklch(0.18 0.005 60 / 5%); }
.theme-newspaper input, .theme-newspaper select, .theme-newspaper textarea { border: 1px solid var(--fg); border-radius: 0; background: var(--surface); font-family: var(--font-body); }
.theme-newspaper input:focus, .theme-newspaper select:focus, .theme-newspaper textarea:focus { outline: 3px double var(--fg); outline-offset: 1px; box-shadow: none; }
.theme-newspaper a { color: var(--fg); text-decoration-thickness: 1px; text-underline-offset: 3px; }
.theme-newspaper a:hover { color: var(--accent-2); text-decoration-color: var(--accent-2); }
.theme-newspaper kbd { font-family: var(--font-mono); font-size: 0.8em; padding: 0.1em 0.4em; border: 1px solid var(--fg); border-radius: 0; background: var(--surface); box-shadow: 1px 1px 0 0 var(--fg); }
.theme-newspaper ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-newspaper ::-webkit-scrollbar-track { background: var(--surface-2); border-left: 1px solid var(--line); }
.theme-newspaper ::-webkit-scrollbar-thumb { background: var(--fg); border-radius: 0; }
.theme-newspaper .label-caps { border-block: 1px solid var(--fg); padding-block: 0.25em; font-weight: 700; }
.theme-newspaper .themed-border { border: 1px solid var(--fg); outline: 1px solid var(--fg); outline-offset: 2px; }
.theme-newspaper button:active { transform: translateY(1px); transition: none; }

/* alt mode: night desk edition — ink and paper swap, the red headline stays */
.theme-newspaper.alt-mode {
  --bg: oklch(0.145 0.008 95.0);
  --surface: oklch(0.185 0.008 95.0);
  --surface-2: oklch(0.225 0.008 95.0);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(0.97 0.005 90 / 40%);
  --shadow-1: 0 1px 0 0 var(--line);
  --shadow-2: 0 0 0 1px var(--line);
  --shadow-3: 0 0 0 3px var(--line);
  --accent: oklch(0.97 0.005 90);
  --accent-fg: oklch(0.145 0.008 95);
  --accent-2: oklch(0.62 0.17 25);
  --danger: oklch(0.62 0.17 25);
  --success: oklch(0.6 0.12 150);
  background-image: radial-gradient(oklch(0.97 0.005 90 / 4%) 1px, transparent 1px);
  background-size: 4px 4px;
}
.theme-newspaper.alt-mode tbody tr:hover { background: oklch(0.97 0.005 90 / 6%); }
.theme-newspaper.alt-mode thead th, .theme-newspaper.alt-mode .label-caps, .theme-newspaper.alt-mode .themed-border, .theme-newspaper.alt-mode input, .theme-newspaper.alt-mode select, .theme-newspaper.alt-mode textarea, .theme-newspaper.alt-mode kbd { border-color: var(--fg); }
.theme-newspaper.alt-mode kbd { box-shadow: 1px 1px 0 0 var(--fg); }
.theme-newspaper.alt-mode a:hover { color: oklch(0.68 0.17 25); text-decoration-color: oklch(0.68 0.17 25); }
.theme-newspaper.alt-mode h2 { border-block-color: var(--fg); }
.theme-newspaper.alt-mode ::-webkit-scrollbar-thumb { background: var(--fg); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
